use std::io::{self, Read};

/// Returns the number of turns required to reduce an opponent's health to 0
/// when each attack deals `strength` damage.
/// This is ceil(health / strength).
fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    let h = health as i64;
    let s = strength as i64;
    (h + s - 1) / s
}

/// Given:
///  a = Takahashi’s health,
///  b = Takahashi’s attack strength,
///  c = Aoki’s health,
///  d = Aoki’s attack strength,
/// returns "Yes" if Takahashi wins (i.e., requires no more turns to defeat Aoki
/// than Aoki needs to defeat Takahashi), otherwise "No".
fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    let takahashi_turns = exec_turns_to_defeat(c, b);
    let aoki_turns     = exec_turns_to_defeat(a, d);
    if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

fn main() {
    // Read four integers from stdin
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();
    let a = iter.next().unwrap().parse::<i8>().unwrap();
    let b = iter.next().unwrap().parse::<i8>().unwrap();
    let c = iter.next().unwrap().parse::<i8>().unwrap();
    let d = iter.next().unwrap().parse::<i8>().unwrap();

    // Compute and print the result
    println!("{}", solve(a, b, c, d));
}